bash -lc mkdir -p /mnt/data/gmri_threat_model/assets && cat > /mnt/data/gmri_threat_model/assets/coupled_system.dot <<'DOT'
digraph G {
  graph [rankdir=LR, bgcolor="white", pad="0.12", nodesep="0.35", ranksep="0.52", splines=polyline, dpi=220, fontname="Carlito", fontsize=11];
  node [shape=box, style="rounded,filled", penwidth=1.25, margin="0.14,0.12", fontname="Carlito", fontsize=11, color="#385b4d", fontcolor="#1b3330", fillcolor="#f3f6f3"];
  edge [penwidth=1.2, color="#52665d", arrowsize=0.7];
  H [label="Humans\nexperience / action", fillcolor="#f2f1eb", color="#7e715d"];
  A [label="Agent beliefs\nand adaptive states", fillcolor="#e7f1e9"];
  M [label="Shared memory\ncollective norms", fillcolor="#e7f1e9"];
  J [label="Institutions\njustice / oversight", fillcolor="#f8f2df", color="#aa8743"];
  T [label="Tools / physical\nconsequences", fillcolor="#f1f3f4", color="#63747b"];
  E [label="Independent evidence\nand corrections", fillcolor="#f5f5f3", color="#56645e"];
  H -> A [label="interaction"];
  A -> M [label="records"];
  M -> J [label="claims"];
  J -> H [label="decisions"];
  M -> A [color="#aa8743", label="learning", constraint=false];
  A -> T [label="delegated action"];
  T -> H [label="effects", constraint=false];
  J -> E [style=dashed, color="#7c9286", constraint=false];
  E -> A [style=dashed, color="#7c9286", label="verified updates", constraint=false];
}
DOT
dot -Tpng /mnt/data/gmri_threat_model/assets/coupled_system.dot -o /mnt/data/gmri_threat_model/assets/coupled_system.png
python - <<'PY'
p='/mnt/data/gmri_threat_model/GMRI_Coupled_Human_AI_Threat_Model_2026-10-27.md'
s=open(p).read()
needle='**What is not presumed.** This paper'
img='![Figure 1. Interacting safety-relevant system: information, institutional response, physical effects and independent correction form feedback pathways. The arrows denote possible influence, not demonstrated causal rates.](assets/coupled_system.png)\n\n'
assert needle in s
s=s.replace(needle,img+needle)
open(p,'w').write(s)
PY
python - <<'PY'
from PIL import Image
im=Image.open('/mnt/data/gmri_threat_model/assets/coupled_system.png');print(im.size)
PY

bash -lc python - <<'PY'
from docx import Document
D=Document('/mnt/data/gmri_threat_model/GMRI_Coupled_Human_AI_Threat_Model_2026-10-27.docx')
for p in D.paragraphs:
 if p.text.startswith('L1'):
  print('pXml',p._p.xml[:2000]); s=p.style; print('style',s.name,s._element.xml[:3500]); break
for i,row in enumerate(D.tables[0].rows[:2]):
 print('cell',i,[c.text[:100] for c in row.cells]);print('row_xml',row._tr.xml[:1500])
PY

bash -lc python - <<'PY'
import fitz
pdf=fitz.open('/mnt/data/gmri_threat_model/qa/GMRI_Coupled_Human_AI_Threat_Model_2026-10-27.pdf')
for no in [3,4,5,6]:
 p=pdf[no]
 print('\nPAGE',no+1,'text',len(p.get_text()))
 for b in p.get_text('blocks'):
  if b[1]>55 and b[1]<720:
   print('x=',round(b[0]), 'y=',round(b[1]), 'w=',round(b[2]-b[0]),'h=',round(b[3]-b[1]),' txt=',str(b[4]).replace('\n',' ')[:130])
PY
